styles:
.page-post { padding-top: clamp(120px, 16vh, 180px); }
.page-post .post { max-width: 820px; margin-inline: auto; }
.post__eyebrow { margin-bottom: 16px; }
.post__eyebrow a { color: var(--red); transition: opacity .25s var(--ease); }
.post__eyebrow a:hover { opacity: .7; }
.post__title {
  font-family: var(--font-display);
  font-size: clamp(34px, 5.2vw, 62px);
  line-height: 1.08; letter-spacing: -0.01em;
  color: var(--grey-900); max-width: 18ch;
}
.post__meta {
  display: flex; align-items: center; flex-wrap: wrap; gap: 10px;
  margin-top: clamp(20px, 3vw, 30px);
  color: var(--grey-500); font-size: 15px;
}
.post__meta img { width: 46px; height: 46px; border-radius: 50%; object-fit: cover; }
.post__meta .who { color: var(--grey-900); font-family: var(--font-display); font-size: 16px; }
.post__meta .sep { color: var(--grey-300); }
.post__cover {
  margin: clamp(30px, 5vw, 52px) 0;
  border-radius: var(--radius-lg); overflow: hidden; background: var(--bg-alt);
}
.post__cover img { width: 100%; height: auto; display: block; }
.post__body { max-width: 720px; margin-inline: auto; }
.post__body > p {
  margin-bottom: 1.4em;
  font-size: clamp(17px, 1.15vw, 19px);
  line-height: 1.85; color: var(--grey-700);
}
.post__body .lede { font-size: clamp(19px, 1.4vw, 22px); color: var(--grey-900); }
.post__body h2 {
  font-family: var(--font-display);
  font-size: clamp(24px, 3.2vw, 36px); line-height: 1.16;
  color: var(--grey-900); margin: 1.7em 0 .55em;
}
.post__body blockquote {
  margin: 0 0 1.4em; padding: 6px 0 6px 22px;
  border-left: 3px solid var(--red);
  font-style: italic; color: var(--grey-500);
  font-size: clamp(16px, 1.1vw, 18px); line-height: 1.8;
}
.post__body strong { color: var(--grey-900); font-weight: 400; }
.post__back {
  display: inline-flex; align-items: center; gap: 10px;
  margin-top: clamp(44px, 6vw, 74px);
  font-family: var(--font-display); font-size: 18px; color: var(--red);
  transition: gap .3s var(--ease);
}
.post__back svg { transition: transform .3s var(--ease); }
.post__back:hover { gap: 14px; }
.post__back:hover svg { transform: translateX(-3px); }
